import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription, DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Checkbox } from '@/components/ui/checkbox';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tag, Plus, Minus, Loader2, Search } from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { isWhatsAppTag, filterCustomTags, getTagDisplayName } from '@/lib/tags';
import { applyContactTagChange, pendingIds } from '@/services/contact-bulk.service';

interface ContactBulkTagDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  contactIds: string[];
  allTags: string[];
  onComplete: () => void;
  /** Recusados pelo banco: o chamador mantém esses IDs selecionados. */
  onPartialComplete?: (refusedIds: string[]) => void;
}

export function ContactBulkTagDialog({
  open, onOpenChange, contactIds, allTags, onComplete, onPartialComplete,
}: ContactBulkTagDialogProps) {
  const [mode, setMode] = useState<'add' | 'remove'>('add');
  const [selectedTags, setSelectedTags] = useState<Set<string>>(new Set());
  const [newTag, setNewTag] = useState('');
  const [search, setSearch] = useState('');
  const [saving, setSaving] = useState(false);

  const filteredTags = useMemo(() => {
    const all = filterCustomTags([...new Set([...allTags, ...(newTag.trim() ? [newTag.trim()] : [])])]);
    if (!search) return all;
    return all.filter(t => t.toLowerCase().includes(search.toLowerCase()));
  }, [allTags, newTag, search]);

  const toggleTag = (tag: string) => {
    const next = new Set(selectedTags);
    if (next.has(tag)) {
      next.delete(tag);
    } else {
      next.add(tag);
    }
    setSelectedTags(next);
  };

  const addNewTag = () => {
    if (!newTag.trim()) return;
    if (isWhatsAppTag(newTag.trim())) return;
    setSelectedTags(prev => new Set(prev).add(newTag.trim()));
    setNewTag('');
  };

  const handleApply = async () => {
    const safeSelected = [...selectedTags].filter(t => !isWhatsAppTag(t));
    if (safeSelected.length === 0) return;
    setSaving(true);
    try {
      // R2-AUTH-013: a mutação devolve quem mudou, quem foi recusado e o que falhou.
      // Antes o SELECT ignorava erro e o laço de UPDATE ignorava o retorno, então o
      // toast anunciava `contactIds.length` mesmo com 0 linhas afetadas.
      const outcome = await applyContactTagChange(
        contactIds,
        mode === 'add' ? { add: safeSelected } : { remove: safeSelected },
      );
      const refused = pendingIds(outcome);

      if (outcome.succeeded.length === 0 && refused.length === 0) {
        // Nada a mudar: todos já estavam no estado desejado (não é falha).
        toast.success(
          mode === 'add'
            ? `As tags selecionadas já estavam nos ${contactIds.length} contatos`
            : `As tags selecionadas já não estavam nos ${contactIds.length} contatos`,
        );
        onComplete();
        onOpenChange(false);
        setSelectedTags(new Set());
        return;
      }

      if (outcome.succeeded.length === 0) {
        // Erro do SDK ou recusa total: falha honesta, sem anunciar sucesso.
        toast.error(
          outcome.failed.length > 0
            ? 'Erro ao atualizar tags. Nenhum contato foi alterado.'
            : 'Nenhum contato foi atualizado. Verifique se você tem permissão.',
        );
        return;
      }

      if (refused.length > 0) {
        toast.warning(`${outcome.succeeded.length} de ${contactIds.length} contatos atualizados`, {
          description: 'Os demais não puderam ser atualizados (sem permissão ou sem alteração).',
        });
        onPartialComplete?.(refused);
      } else {
        toast.success(
          mode === 'add'
            ? `${safeSelected.length} tag(s) adicionada(s) a ${outcome.succeeded.length} contatos`
            : `${safeSelected.length} tag(s) removida(s) de ${outcome.succeeded.length} contatos`,
        );
        onComplete();
      }
      onOpenChange(false);
      setSelectedTags(new Set());
    } catch {
      toast.error('Erro ao atualizar tags');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent aria-describedby={undefined} className="max-w-md">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <Tag className="w-5 h-5 text-primary" />
            Tags em Lote
          </DialogTitle>
          <DialogDescription>
            {mode === 'add' ? 'Adicionar' : 'Remover'} tags de {contactIds.length} contato(s)
          </DialogDescription>
        </DialogHeader>

        {/* Mode Toggle */}
        <div className="flex gap-2">
          <Button
            variant={mode === 'add' ? 'default' : 'outline'}
            size="sm"
            onClick={() => setMode('add')}
            className="flex-1 gap-1.5"
          >
            <Plus className="w-3.5 h-3.5" />
            Adicionar
          </Button>
          <Button
            variant={mode === 'remove' ? 'destructive' : 'outline'}
            size="sm"
            onClick={() => setMode('remove')}
            className="flex-1 gap-1.5"
          >
            <Minus className="w-3.5 h-3.5" />
            Remover
          </Button>
        </div>

        {/* Search */}
        <div className="relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-muted-foreground" />
          <Input
            value={search}
            onChange={e => setSearch(e.target.value)}
            placeholder="Buscar tags..."
            className="pl-9 h-8 text-xs"
          />
        </div>

        {/* Tag List */}
        <ScrollArea className="h-48">
          <div className="space-y-1">
            <AnimatePresence>
              {filteredTags.map(tag => (
                <motion.label
                  key={tag}
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
                  className={cn(
                    'flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-colors',
                    selectedTags.has(tag) ? 'bg-primary/10 border border-primary/20' : 'hover:bg-muted/50'
                  )}
                >
                  <Checkbox
                    checked={selectedTags.has(tag)}
                    onCheckedChange={() => toggleTag(tag)}
                    className="w-3.5 h-3.5"
                  />
                  <Badge variant="secondary" className="text-xs">{getTagDisplayName(tag)}</Badge>
                </motion.label>
              ))}
            </AnimatePresence>
          </div>
        </ScrollArea>

        {/* Add New Tag */}
        {mode === 'add' && (
          <div className="flex gap-2">
            <Input
              value={newTag}
              onChange={e => setNewTag(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && addNewTag()}
              placeholder="Nova tag..."
              className="h-8 text-xs flex-1"
            />
            <Button variant="outline" size="sm" onClick={addNewTag} disabled={!newTag.trim()}>
              <Plus className="w-3.5 h-3.5" />
            </Button>
          </div>
        )}

        {/* Selected Summary */}
        {selectedTags.size > 0 && (
          <div className="flex flex-wrap gap-1">
            {[...selectedTags].map(t => (
              <Badge
                key={t}
                variant={mode === 'add' ? 'default' : 'destructive'}
                className="text-3xs h-5 cursor-pointer"
                onClick={() => toggleTag(t)}
              >
                {getTagDisplayName(t)} ×
              </Badge>
            ))}
          </div>
        )}

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>Cancelar</Button>
          <Button
            onClick={handleApply}
            disabled={saving || [...selectedTags].filter(t => !isWhatsAppTag(t)).length === 0}
            className="gap-1.5"
          >
            {saving ? <Loader2 className="w-4 h-4 animate-spin" /> : mode === 'add' ? <Plus className="w-4 h-4" /> : <Minus className="w-4 h-4" />}
            {mode === 'add' ? 'Adicionar' : 'Remover'} {[...selectedTags].filter(t => !isWhatsAppTag(t)).length} Tag(s)
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
